var t2s = func() *strings.Replacer {
	t, s := []rune(tradChars), []rune(simpChars)
	var pairs []string
	for i := range t {
		pairs = append(pairs, string(t[i]), string(s[i]))
	}
	return strings.NewReplacer(pairs...)
}()

func toSimplified(s string) string { return t2s.Replace(s) }
